// Intent is a task, not a trigger on the word “subtitles”. Copywriting is not ASR.
export function productionIntent(text){
 const s=String(text||'');if(/без\s+субтитр/i.test(s))return null;
 const captions=/субтитр|расшифр|распозна.{0,15}реч/i.test(s),ad=/реклам|продаж|покупател/i.test(s),write=/придум|напиш|сочин|текст.{0,30}сам|текст для видео/i.test(s);
 if(!captions&&!(ad&&/ролик|видео/i.test(s)))return null;
 return {kind:ad||write?'script':'speech',advert:ad,cover:/обложк/i.test(s)||ad,prompt:s.slice(0,6000)};
}
export function productionPreferences(v={}){return {language:['ru','en'].includes(v.language)?v.language:'ru',style:['karaoke','outline','plate','plain'].includes(v.style)?v.style:'karaoke',color:/^#[a-f0-9]{6}$/i.test(v.color||'')?v.color:'#ffffff',highlight:/^#[a-f0-9]{6}$/i.test(v.highlight||'')?v.highlight:'#f4d740',font:['Golos Text','Roboto Condensed'].includes(v.font)?v.font:'Roboto Condensed',position:['top','center','bottom'].includes(v.position)?v.position:'bottom',theme:['auto','automotive','coffee','technology','travel','editorial'].includes(v.theme)?v.theme:'auto',gradient:v.gradient!==false,topic:String(v.topic||'').slice(0,1000),duration:Math.max(5,Math.min(180,Number(v.duration)||30)),visualConsent:v.visualConsent===true};}
export function preferencesFromReply(text,previous={}){const v={...previous},s=String(text);if(/англ|english/i.test(s))v.language='en';if(/русск/i.test(s))v.language='ru';for(const [re,color]of [[/ж[её]лт/i,'#f4d740'],[/красн/i,'#ff654f'],[/бел/i,'#ffffff'],[/зел[её]н/i,'#8ee3ac'],[/син|голуб/i,'#83bfff']])if(re.test(s))v.color=color;const hex=s.match(/#[a-f0-9]{6}/i);if(hex)v.color=hex[0];if(/reels|рилс|караоке|выдел/i.test(s))v.style='karaoke';if(/контур/i.test(s))v.style='outline';if(/подложк/i.test(s))v.style='plate';if(/сверху/i.test(s))v.position='top';if(/центр/i.test(s))v.position='center';if(/снизу/i.test(s))v.position='bottom';return productionPreferences(v);}
const THEMES={automotive:{accent:'#eff34a',gradientEnd:'#0b172b',layout:'editorial'},coffee:{accent:'#f1c58a',gradientEnd:'#3e2118',layout:'poster'},technology:{accent:'#9de9ef',gradientEnd:'#132f45',layout:'editorial'},travel:{accent:'#e7dcb7',gradientEnd:'#15392f',layout:'poster'},editorial:{accent:'#f4f1e9',gradientEnd:'#25232d',layout:'split'}};
export function thematicCover(cover={},text='',preferences={}){const p=productionPreferences(preferences);let theme=p.theme;if(theme==='auto')theme=/авто|bmw|машин|car|мотор|peugeot/i.test(text)?'automotive':/коф|coffee|кафе/i.test(text)?'coffee':/техн|прилож|гаджет|software|сайт/i.test(text)?'technology':/путеш|гор|море|travel/i.test(text)?'travel':'editorial';const palette=THEMES[theme];return {...palette,...cover,designVersion:2,theme,gradient:p.gradient,accent:/^#[a-f0-9]{6}$/i.test(cover.accent||'')?cover.accent:palette.accent,gradientEnd:/^#[a-f0-9]{6}$/i.test(cover.gradientEnd||'')?cover.gradientEnd:palette.gradientEnd,position:cover.position||'bottom',textSize:cover.textSize||12,shade:Math.min(.35,cover.shade??.2)};}
export function scriptCues(lines,duration){if(!Array.isArray(lines)||!lines.length||lines.length>40)throw Error('ИИ должен вернуть рекламный текст, а не расшифровку.');const texts=lines.map(x=>String(x).trim());if(texts.some(x=>!x||x.length>180))throw Error('Слишком длинная рекламная реплика.');const weights=texts.map(x=>Math.max(3,x.split(/\s+/).length)),sum=weights.reduce((a,b)=>a+b,0);let at=0;return texts.map((text,i)=>{const start=at;at=i===texts.length-1?duration:at+duration*weights[i]/sum;return {start,end:at,text}});}

export function safeProductionJob(value){if(!value||!['speech','script'].includes(value.request?.kind)||typeof value.request.prompt!=='string')return undefined;return {request:{kind:value.request.kind,prompt:value.request.prompt.slice(0,6000),advert:!!value.request.advert,cover:!!value.request.cover},preferences:productionPreferences(value.preferences),status:value.status==='done'?'done':'pending'};}
